<script setup lang="ts">
import { computed } from 'vue'
import { ElButton, ElTag } from 'element-plus'
import { dateLabel } from '../../../shared/console'
import FeatureCatalog from './FeatureCatalog.vue'
import { channelLabel } from '../../../shared/memoryStatus'
const props=defineProps<{summary:any}>()
defineEmits<{open:[page:string];conversation:[id:string]}>()
const stats=computed(()=>[
  {key:'sessions',label:'历史对话',unit:'段',hint:'当前账号保存的全部会话',icon:'▤',tone:'blue'},
  {key:'messages',label:'原始消息',unit:'条',hint:'可搜索、逐条定位的完整原话',icon:'≋',tone:'teal'},
  {key:'memories',label:'有效长期记忆',unit:'条',hint:'与原始对话分开管理',icon:'◈',tone:'purple'},
  {key:'pending_reviews',label:'待审核记忆',unit:'条',hint:'LLM自动处理，疑问留人工辅助',icon:'◎',tone:'amber'},
])
</script>
<template>
  <div class="stat-grid" :aria-busy="!summary"><template v-if="!summary"><div v-for="s in stats" :key="s.key" class="stat-card stat-skeleton" role="status" aria-label="正在读取数据"><span class="stat-icon stat-skeleton-box" :class="s.tone"></span><span class="stat-label">{{ s.label }}</span><div><strong class="stat-skeleton-line"></strong><span>{{ s.unit }}</span></div><small class="stat-skeleton-line stat-skeleton-line-short"></small></div></template><template v-else><button v-for="s in stats" :key="s.key" class="stat-card" @click="$emit('open',s.key==='sessions'||s.key==='messages'?'conversations':s.key==='memories'?'memories':'reviews')"><span class="stat-icon" :class="s.tone">{{ s.icon }}</span><span class="stat-label">{{ s.label }}</span><div><strong>{{ summary?.[s.key]??'—' }}</strong><span>{{ s.unit }}</span></div><small>{{ s.hint }}</small></button></template></div>
  <div class="dashboard-grid"><section class="panel"><div class="section-title"><div><h2>最近的对话记录</h2><p>直接展开上下文，无需进入审核表单。</p></div><button class="text-button" @click="$emit('open','conversations')">查看全部 →</button></div><table v-if="summary?.recent?.length" class="data-table"><thead><tr><th>会话 / 原文预览</th><th>来源</th><th>消息</th><th>最近记录</th><th/></tr></thead><tbody><tr v-for="item in summary.recent" :key="item.id" @click="$emit('conversation',item.id)" tabindex="0" @keydown.enter="$emit('conversation',item.id)"><td><strong>{{ item.title }}</strong><p>{{ item.preview }}</p></td><td><el-tag size="small" :type="item.origin.kind==='imported'?'info':'success'">{{ channelLabel(item.origin) }}</el-tag></td><td>{{ item.message_count }}</td><td>{{ dateLabel(item.updated_at) }}</td><td class="table-arrow">↗</td></tr></tbody></table><div v-else-if="!summary" class="table-skeleton" role="status" aria-label="正在读取账号数据"><div v-for="i in 4" :key="i" class="table-skeleton-row"><span class="skeleton-line"></span><span class="skeleton-line skeleton-line-short"></span></div><p class="skeleton-note">正在读取账号数据；这里不代表历史为空。</p></div><div v-else class="empty"><span>▤</span><h3>当前账号尚无对话</h3><p>进入 Chat 创建自己的记录，其他账号的数据不会出现在这里。</p><a href="/" class="inline-link">打开 Chat →</a></div></section>
  <aside class="panel data-health"><div class="section-title"><h2>数据与记忆概况</h2><span class="live-indicator">实时读取</span></div><div class="health-row"><span>导入语料来源</span><strong>{{ summary?.datasets??'—' }}</strong></div><div class="health-row"><span>导入资料会话</span><strong>{{ summary?.imported_conversations??'—' }}</strong></div><div class="health-row"><span>结构化 Claim</span><strong>{{ summary?.claims??'—' }}</strong></div><div class="health-row"><span>待审 Claim</span><strong>{{ summary?.claim_statuses?.pending??0 }}</strong></div><div class="health-row"><span>待处理 / 重试任务</span><strong>{{ summary?.memory_jobs_pending??'—' }}</strong></div><div class="health-row"><span>失败任务</span><strong>{{ summary?.memory_jobs_failed??'—' }}</strong></div><div class="info-note"><strong>对话记录 ≠ 已批准记忆</strong><p>导入的公开对话保留原始来源；它们不会自动变成当前账号的个人事实。记忆为空时，仍可完整浏览历史。</p></div></aside></div>
  <section class="panel memory-guide"><div class="section-title"><div><h2>从对话到长期记忆</h2><p>保存对话 → 提取候选 → LLM审核 → 长期访问</p></div><el-button @click="$emit('open','pipeline')">为什么没有记忆？</el-button></div><p>导入资料供研究与浏览；日常提问不一定值得长期保存。有效本人原话可启动LLM提取与审核；低风险自动入库。</p><div class="actions"><el-button type="primary" @click="$emit('open','conversations')">从本人原话开始</el-button><el-button @click="$emit('open','reviews')">审核候选</el-button></div></section><div class="quick-links"><button @click="$emit('open','explorer')"><span>◈</span><div><strong>结构化记忆与适用条件</strong><p>管理属性、条件、冲突和不可变修订；需先有核对过的事实</p></div><span>→</span></button><button @click="$emit('open','retrieval')"><span>⌕</span><div><strong>检索与证据诊断</strong><p>检查为什么召回或过滤，不会生成聊天答复</p></div><span>→</span></button><button @click="$emit('open','evaluation')"><span>▥</span><div><strong>实验结果账本</strong><p>只读查看已有运行与失败，不自动开始评测</p></div><span>→</span></button></div>
<FeatureCatalog @open="$emit('open',$event)"/>
</template>

<style scoped>
.memory-guide>p{font-size:12px;line-height:1.9;color:#7d8e76}.quick-links p{line-height:1.8!important}.memory-guide .actions{flex-wrap:wrap}
.stat-skeleton{cursor:default}.stat-skeleton-box{background:#e7ece4!important;animation:skeleton-pulse 1.2s ease-in-out infinite alternate}.stat-skeleton-line{display:inline-block;width:52px;height:26px;border-radius:6px;background:#e7ece4;animation:skeleton-pulse 1.2s ease-in-out infinite alternate}.stat-skeleton-line-short{width:120px;height:10px;margin-top:8px}.table-skeleton{padding:10px 4px}.table-skeleton-row{display:flex;gap:18px;padding:14px 6px;border-bottom:1px solid #e7ece4}.skeleton-line{display:inline-block;height:13px;width:min(320px,42vw);border-radius:5px;background:#edf0ea;animation:skeleton-pulse 1.2s ease-in-out infinite alternate}.skeleton-line-short{width:64px}.skeleton-note{font-size:11px;color:#8b9b8a;margin:12px 6px 4px}.table-skeleton-row,.stat-skeleton-line,.skeleton-line,.stat-skeleton-box{animation:skeleton-pulse 1.2s ease-in-out infinite alternate}@keyframes skeleton-pulse{to{opacity:.45}}@media(prefers-reduced-motion:reduce){.stat-skeleton-box,.stat-skeleton-line,.skeleton-line,.table-skeleton-row{animation:none}}
</style>
